function overtimeRows(employees,year){const weeks=isoWeekStarts(year),todayStart=shiftDay(localDateInput(),-((new Date(`${localDateInput()}T12:00:00`).getDay()+6)%7)),rows=[];for(const employee of employees){const activityDates=[...db.entries.filter(e=>e.employee===employee.name).map(e=>localDayKey(e.start)),...db.absences.filter(a=>a.employee===employee.name).map(a=>localDayKey(a.start))];if(db.clocks?.[employee.name])activityDates.push(localDayKey(db.clocks[employee.name].started));if(!activityDates.length)continue;const firstDay=activityDates.sort()[0],firstWeek=shiftDay(firstDay,-((new Date(`${firstDay}T12:00:00`).getDay()+6)%7));for(const weekStart of weeks){if(weekStart<firstWeek||weekStart>todayStart)continue;const days=Array.from({length:7},(_,i)=>shiftDay(weekStart,i)),summary=weeklyAttendance(employee,weekStart),weekEndTime=(new Date(`${days[6]}T12:00:00`).getTime()/1000)-978307200;rows.push(`<tr><td>${esc(employee.name)}</td><td>KW ${isoWeekNumber(weekStart)}</td><td>${date((new Date(`${weekStart}T12:00:00`).getTime()/1000)-978307200)}–${date(weekEndTime)}</td><td>${duration(summary.scheduled)}</td><td>${duration(summary.actual)}</td><td>${duration(summary.holidayCredit)}</td><td>${duration(summary.absenceCredit)}</td><td>${duration(summary.overtime)}</td><td>${duration(summary.minus)}</td><td>${summary.holidays.join('<br>')||'—'}</td><td>${weekStart===todayStart?'Vorläufig':'Abgeschlossen'}</td></tr>`);}}return rows.join('')||'<tr><td colspan="11">Für dieses Jahr liegen noch keine Arbeitszeiten oder Abwesenheiten vor.</td></tr>';}
function holidayRows(year){return [...publicHolidaysBW(year)].sort(([a],[b])=>a.localeCompare(b)).map(([key,name])=>{const hours=weekdayTargetHours(key),timestamp=(new Date(`${key}T12:00:00`).getTime()/1000)-978307200;return `<tr><td>${date(timestamp)}</td><td>${new Date(`${key}T12:00:00`).toLocaleDateString('de-DE',{weekday:'long'})}</td><td>${esc(name)}</td><td>${fmt(hours)} Std.</td></tr>`;}).join('');}function projectHours(jobID,employeeName){return db.entries.filter(e=>String(e.jobID||'').toUpperCase()===String(jobID||'').toUpperCase()&&(!employeeName||e.employee===employeeName)).reduce((sum,e)=>sum+entrySeconds(e),0)+Object.entries(db.clocks||{}).filter(([name,c])=>String(c.jobID||'').toUpperCase()===String(jobID||'').toUpperCase()&&(!employeeName||name===employeeName)).reduce((sum,[,c])=>sum+clockSeconds(c),0);}
function employeeStatus(employee){const clock=db.clocks?.[employee.name];if(clock)return clock.segmentStart?'Arbeitet':'Pause';const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime()/1000-978307200,absence=db.absences.find(a=>a.employee===employee.name&&a.start<=today&&a.end>=today);return absence?.type==='Urlaub'?'Urlaub':absence?.type==='Krankmeldung'?'Krank':'Keine Arbeitszeit';}
function restoreSalvatoreEmployeeName(){const employee=db.employees.find(e=>e.id==='A1B00000-0000-4000-8000-000000000001');if(!employee)return false;const target='Salvatore Albo',aliases=new Set([employee.name,db.employee,'Salvatore']);let changed=employee.name!==target;employee.name=target;if(db.employee!=='Salvatore Albo'){db.employee=target;changed=true;}for(const row of db.entries)if(aliases.has(row.employee)&&row.employee!==target){row.employee=target;changed=true;}for(const row of db.absences)if(aliases.has(row.employee)&&row.employee!==target){row.employee=target;changed=true;}for(const row of db.reports)if(aliases.has(row.author)&&row.author!==target){row.author=target;changed=true;}db.clocks=db.clocks||{};for(const alias of aliases){if(alias===target||!db.clocks[alias])continue;if(!db.clocks[target]||(!db.clocks[target].segmentStart&&db.clocks[alias].segmentStart))db.clocks[target]=db.clocks[alias];delete db.clocks[alias];changed=true;}return changed;}
