function notify(text,error=false){message.hidden=false;message.textContent=text;message.setAttribute('role',error?'alert':'status');}
async function api(path,options={}){const res=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const body=await res.json();if(!res.ok){const err=Error(body.error||'Verbindung fehlgeschlagen.');err.status=res.status;err.conflicts=body.conflicts;throw err;}return body;}
async function load(){workspace=await api('workspace');db=structuredClone(workspace.backup.database);for(const field of ['appointments','materials','services','checklists','absences','overtimeUses'])db[field]=db[field]||[];if(workspace.identity?.role==='admin'&&restoreSalvatoreEmployeeName())await save();try{logoInfo=(await api('logo')).logo;}catch{logoInfo=null;}render();}
function paintLogoCrop(){
 const canvas=document.getElementById('logo-crop-canvas');if(!canvas||!logoImage)return;const ctx=canvas.getContext('2d');
 if(!logoCrop){const ratio=130/49,w=Math.min(canvas.width,canvas.height*ratio),h=w/ratio;logoCrop={x:(canvas.width-w)/2,y:(canvas.height-h)/2,w,h};}
 ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(logoImage,0,0,canvas.width,canvas.height);ctx.fillStyle='rgba(0,0,0,.52)';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(logoImage,logoCrop.x/logoPreviewScale,logoCrop.y/logoPreviewScale,logoCrop.w/logoPreviewScale,logoCrop.h/logoPreviewScale,logoCrop.x,logoCrop.y,logoCrop.w,logoCrop.h);ctx.strokeStyle='#ffffff';ctx.lineWidth=Math.max(2,canvas.width/600);ctx.strokeRect(logoCrop.x,logoCrop.y,logoCrop.w,logoCrop.h);
}
function logoCropPoint(event,canvas){const bounds=canvas.getBoundingClientRect();return {x:(event.clientX-bounds.left)*canvas.width/bounds.width,y:(event.clientY-bounds.top)*canvas.height/bounds.height};}
function beginLogoCrop(file){
 if(!file)return;if(file.size>10*1024*1024){notify('Das Bild darf höchstens 10 MB groß sein.',true);return;}
 if(!['image/png','image/jpeg','image/webp'].includes(file.type)){notify('Bitte ein PNG-, JPG- oder WebP-Bild auswählen.',true);return;}
 const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{logoImage=img;logoFile=file;logoPreviewScale=Math.min(1,1200/img.naturalWidth,700/img.naturalHeight);const canvas=document.getElementById('logo-crop-canvas');if(!canvas)return;canvas.width=Math.max(1,Math.round(img.naturalWidth*logoPreviewScale));canvas.height=Math.max(1,Math.round(img.naturalHeight*logoPreviewScale));logoCrop=null;document.getElementById('logo-crop-area').hidden=false;paintLogoCrop();URL.revokeObjectURL(url);};img.onerror=()=>{URL.revokeObjectURL(url);notify('Das Bild konnte nicht geöffnet werden.',true);};img.src=url;
}
function bindLogoCrop(){const canvas=document.getElementById('logo-crop-canvas');if(!canvas)return;canvas.addEventListener('pointerdown',event=>{if(!logoImage)return;canvas.setPointerCapture(event.pointerId);logoDrag=logoCropPoint(event,canvas);});canvas.addEventListener('pointermove',event=>{if(!logoDrag)return;const p=logoCropPoint(event,canvas),ratio=130/49,dx=p.x-logoDrag.x,dy=p.y-logoDrag.y;let w=Math.abs(dx),h=Math.abs(dy);if(h===0||w/h>=ratio)h=w/ratio;else w=h*ratio;const maxW=Math.min(canvas.width,canvas.height*ratio);if(w>maxW){w=maxW;h=w/ratio;}let x=dx<0?logoDrag.x-w:logoDrag.x,y=dy<0?logoDrag.y-h:logoDrag.y;x=Math.max(0,Math.min(canvas.width-w,x));y=Math.max(0,Math.min(canvas.height-h,y));if(w>8&&h>8)logoCrop={x,y,w,h};paintLogoCrop();});const end=()=>{logoDrag=null;};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);}
async function saveLogoCrop(){if(!logoImage||!logoCrop||!logoFile)throw Error('Wähle zuerst ein Logo-Bild aus.');const output=document.createElement('canvas');output.width=1560;output.height=Math.round(output.width*49/130);const ctx=output.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,output.width,output.height);ctx.drawImage(logoImage,logoCrop.x/logoPreviewScale,logoCrop.y/logoPreviewScale,logoCrop.w/logoPreviewScale,logoCrop.h/logoPreviewScale,0,0,output.width,output.height);const blob=await new Promise(resolve=>output.toBlob(resolve,'image/png'));if(!blob)throw Error('Der Bildausschnitt konnte nicht erstellt werden.');const reader=new FileReader(),data=await new Promise((resolve,reject)=>{reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Bild konnte nicht gelesen werden.'));reader.readAsDataURL(blob);});const base=logoFile.name.replace(/\.[^.]+$/,'').slice(0,100);logoInfo=(await api('logo',{method:'POST',body:JSON.stringify({name:base+'-Logo.png',mime:'image/png',data})})).logo;logoImage=null;logoFile=null;logoCrop=null;render();notify('Zugeschnittenes Logo gespeichert und übernommen.');}
async function save(){if(busy)return false;busy=true;unsaved=true;try{const identity=workspace?.identity,result=await api('sync',{method:'POST',body:JSON.stringify({workspaceID:workspace.workspaceID,baseRevision:workspace.revision,baseSnapshot:{revision:workspace.revision,proof:workspace.proof,database:workspace.backup.database},backup:{version:1,database:db,photos:{}}})});workspace={...result,identity};db=structuredClone(result.backup.database);unsaved=false;return true;}catch(e){notify(e.message+(e.conflicts?' Betroffene Datensätze: '+e.conflicts.map(c=>c.collection).join(', '):''),true);return false;}finally{busy=false;}}
