function absenceDateKeys(absence,year,weekdaysOnly=false){const start=new Date((absence.start+978307200)*1000),end=new Date((absence.end+978307200)*1000),cursor=new Date(start.getFullYear()<year?year:start.getFullYear(),start.getFullYear()<year?0:start.getMonth(),start.getFullYear()<year?1:start.getDate()),last=new Date(end.getFullYear()>year?year:end.getFullYear(),end.getFullYear()>year?11:end.getMonth(),end.getFullYear()>year?31:end.getDate());cursor.setHours(0,0,0,0);last.setHours(0,0,0,0);if(cursor>last)return [];const keys=[];for(;cursor<=last;cursor.setDate(cursor.getDate()+1)){if(!weekdaysOnly||![0,6].includes(cursor.getDay()))keys.push(`${cursor.getFullYear()}-${String(cursor.getMonth()+1).padStart(2,'0')}-${String(cursor.getDate()).padStart(2,'0')}`);}return keys;}
