 if(a==='worker-start'||a==='worker-start-project'){const jobID=document.getElementById('time-job')?.value;if(!jobID){notify('Lege zuerst eine Baustelle an oder wähle eine aus.',true);return;}db.clocks=db.clocks||{};const identity=workspace.identity||{},name=db.employees.find(e=>e.id===identity.employeeID)?.name||db.employee;db.clocks[name]={jobID,started:swiftNow(),segmentStart:swiftNow(),accumulated:0};if(await save()){render();notify(a==='worker-start'?'Kommen erfasst.':'Projekt gestartet; die Zeit zählt ab jetzt als Arbeitszeit.');}}
