document.addEventListener('change',event=>{if(event.target.name==='deliveryAddressDifferent'&&editing?.kind==='jobs'){const wrap=document.getElementById('job-delivery-address-wrap'),input=document.getElementById('f-deliveryAddress');if(wrap)wrap.hidden=!event.target.checked;if(input)input.required=event.target.checked;}if(event.target.dataset.checklistChoice&&editing?.kind==='reports')editing.row.checklistChoices[event.target.dataset.checklistChoice]=event.target.value;if(event.target.id==='customer-choice'&&event.target.value){const customer=db.customers.find(c=>c.id===event.target.value);document.getElementById('f-customer').value=customerDisplay(customer);document.getElementById('f-address').value=customer.address;}if(event.target.id==='appointment-customer'&&editing){const c=db.customers.find(x=>x.id===event.target.value);if(c){editing.row.customerID=c.id;editing.row.customer=customerDisplay(c);if(editing.row.sameAddress!==false){const f=document.getElementById('f-deliveryAddress');if(f)f.value=c.address;}}}if(event.target.name==='sameAddress'&&event.target.checked&&editing?.kind==='appointments'){const c=db.customers.find(x=>x.id===document.getElementById('appointment-customer')?.value),f=document.getElementById('f-deliveryAddress');if(c&&f)f.value=c.address;}if(event.target.id==='my-times-project'){myTimesProject=event.target.value;render();}if(event.target.id==='time-report-month'){reportMonth=Number(event.target.value);render();}if(event.target.id==='time-report-year'){reportYear=Number(event.target.value);render();}if(event.target.id==='logo-file')beginLogoCrop(event.target.files[0]);});
document.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const values=Object.fromEntries(new FormData(event.target));
 if(event.target.id==='overtime-use-form'){const identity=workspace.identity||{},employee=db.employees.find(e=>e.id===values.employeeID),dateValue=Date.parse(`${values.date}T00:00:00`)/1000-978307200,hours=Number(values.hours),error=document.getElementById('form-error');if(!employee||!Number.isFinite(dateValue)||values.date>localDateInput()||!Number.isFinite(hours)||hours<=0||hours>24||Math.abs(hours*4-Math.round(hours*4))>0.0001){if(error)error.textContent='Bitte Mitarbeiter, ein gültiges vergangenes Datum und eine gültige Stundenzahl angeben.';return;}if(identity.role!=='admin'&&employee.id!==identity.employeeID){if(error)error.textContent='Du kannst nur dein eigenes Überstundenkonto ändern.';return;}const available=overtimeLedger(employee,dateValue).balance/3600;if(hours>available+0.0001){if(error)error.textContent=`Am gewählten Datum sind nur ${fmt(available)} Überstunden verfügbar.`;return;}db.overtimeUses=db.overtimeUses||[];db.overtimeUses.push({id:uuid(),employee:employee.name,date:dateValue,hours,note:String(values.note||'').trim()});if(await save()){timeTab='overtime';render();notify('Überstundenabbau gespeichert.');}return;}
 if(event.target.id==='absence-form'){const selected=db.employees.find(e=>e.id===values.employeeID),identity=workspace.identity||{},start=Date.parse(`${values.startDate}T00:00:00`)/1000-978307200,end=Date.parse(`${values.endDate}T23:59:59`)/1000-978307200;if(!selected||!Number.isFinite(start)||!Number.isFinite(end)||end<start){document.getElementById('form-error').textContent='Bitte Mitarbeiter und einen gültigen Zeitraum auswählen.';return;}if(identity.role!=='admin'&&selected.id!==identity.employeeID){document.getElementById('form-error').textContent='Du kannst nur eine eigene Abwesenheit eintragen.';return;}db.absences.push({id:uuid(),type:values.type,employee:selected.name,start,end,status:values.type==='Krankmeldung'?'Gemeldet':'Beantragt'});if(await save()){absenceFormType=null;render();notify(`${values.type} gespeichert.`);}return;}
 if(event.target.id==='manual-position-form'&&editing?.kind==='reports'){const form=new FormData(event.target),quantity=Number(form.get('quantity')),price=Number(form.get('price')),name=String(form.get('name')||'').trim();if(name&&quantity>0&&price>=0){editing.row.positions.push({kind:String(form.get('kind')),name,quantity,price,unit:String(form.get('unit')||'')});const list=document.getElementById('report-position-list');list.innerHTML=editing.row.positions.map((p,i)=>`<div class="position-row"><span>${esc(p.kind)} · ${esc(p.name)} · Menge ${fmt(p.quantity)} ${esc(p.unit||'')} · ${fmt(p.quantity*p.price)} €</span>${action('Entfernen','remove-position',`data-index="${i}"`)}</div>`).join('');document.querySelector('.report-picker-overlay')?.remove();}return;}
 if(event.target.id==='auth-form'){try{const mode=event.target.dataset.mode;await api(mode==='setup'?'setup':'login',{method:'POST',body:JSON.stringify(values)});await load();page='overview';render();}catch(e){const error=document.getElementById('form-error');if(error)error.textContent=e.message;}return;}
 if(event.target.id==='user-form'){
  const form=event.target,active=new FormData(form).has('active'),payload={...values,active};if(!payload.password)delete payload.password;
  try{if(userEditing.isNew){await api('users',{method:'POST',body:JSON.stringify(payload)});}else{await api('users/'+encodeURIComponent(userEditing.row.id),{method:'PUT',body:JSON.stringify(payload)});}userEditing=null;await loadUsers();render();notify('Benutzerkonto gespeichert.');}catch(e){const error=document.getElementById('form-error');if(error)error.textContent=e.message;}return;
 }
 if(event.target.id==='edit-form'){
  const {kind,row}=editing,next={...row,...values};if(kind==='employees')next.active=Object.hasOwn(values,'active');if(kind==='jobs'){next.deliveryAddressDifferent=Object.hasOwn(values,'deliveryAddressDifferent');next.deliveryAddress=next.deliveryAddressDifferent?String(values.deliveryAddress||'').trim():next.address;if(next.deliveryAddressDifferent&&!next.deliveryAddress){document.getElementById('form-error').textContent='Bitte die abweichende Lieferadresse eintragen.';return;}next.serviceIDs=Array.from(document.querySelectorAll('[data-project-service]:checked'),x=>x.dataset.projectService);next.materialIDs=Array.from(document.querySelectorAll('[data-project-material]:checked'),x=>x.dataset.projectMaterial);}if(kind==='appointments'){const c=db.customers.find(x=>x.id===values.customerID);next.customer=c?customerDisplay(c):'';next.sameAddress=Object.hasOwn(values,'sameAddress');next.date=Date.parse(values.dateLocal)/1000-978307200;if(next.sameAddress&&c)next.deliveryAddress=c.address;}if(kind==='customers'){next.customerNumber=String(values.customerNumber||'').trim();next.firstName=String(values.firstName||'').trim();next.lastName=String(values.lastName||'').trim();next.companyName=String(values.companyName||'').trim();next.landline=String(values.landline||'').trim();next.mobile=String(values.mobile||'').trim();next.email=String(values.email||'').trim();next.address=String(values.address||'').trim();next.name=next.type==='Firmenkunde'?next.companyName:[next.firstName,next.lastName].filter(Boolean).join(' ').trim();next.phone=next.landline;if(!next.name){document.getElementById('form-error').textContent=next.type==='Firmenkunde'?'Bitte den Firmennamen eingeben.':'Bitte Vorname und Nachname eingeben.';return;}}if(kind==='materials'||kind==='services')next.price=Number(values.price);if(kind==='checklists')next.items=(values.itemsText||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
  if(kind==='appointments'){next.employeeID=values.employeeID;next.jobID=values.jobID;}
  if(kind==='reports'){
   stopReportDictation();next.internalNotes=values.internalNotes||'';next.completed=Object.hasOwn(values,'completed');
   next.positions=row.positions||[];next.checklistIDs=row.checklistIDs||[];next.checklistChoices=row.checklistChoices||{};
   const publicChanged=!editing.isNew&&['jobID','title','author','text','materials','customerName','photos','measurements','catalogIDs','checklistIDs','checklistChoices','positions'].some(key=>JSON.stringify(editing.initialPublic[key]??null)!==JSON.stringify(next[key]??null));
   if(publicChanged)next.completed=false;
   for(const key of ['customerSignature','workerSignature']){if(publicChanged||!signatureDraft[key])delete next[key];else next[key]=signatureDraft[key];}
   if(next.completed&&(!String(next.customerName||'').trim()||!next.customerSignature||!next.workerSignature)){document.getElementById('form-error').textContent='Zum Abschließen bitte Kundenname sowie beide Unterschriften ergänzen. Bei Änderungen am Bericht musst du erneut unterschreiben.';return;}
  }
  if(kind==='employees'&&db.employees.some(e=>e.id!==row.id&&e.name===next.name)){document.getElementById('form-error').textContent='Dieser Mitarbeitername existiert bereits.';return;}
  if(kind==='employees'&&row.name!==next.name){const oldClock=db.clocks?.[row.name],newClock=db.clocks?.[next.name];if(oldClock){if(!newClock||(!newClock.segmentStart&&oldClock.segmentStart))db.clocks[next.name]=oldClock;delete db.clocks[row.name];}db.entries.forEach(e=>{if(e.employee===row.name)e.employee=next.name;});db.absences.forEach(a=>{if(a.employee===row.name)a.employee=next.name;});db.reports.forEach(r=>{if(r.author===row.name)r.author=next.name;});if(db.employee===row.name)db.employee=next.name;}
  if(kind==='customers'&&!editing.isNew&&row.name!==next.name)db.jobs.forEach(j=>{if(j.customer===row.name){j.customer=next.name;j.address=next.address;}});
  const index=db[kind].findIndex(r=>r.id===row.id);if(index>=0)db[kind][index]=next;else db[kind].unshift(next);
  if(await save()){editing=null;render();notify('Gespeichert.');}else{editing.row=next;render();document.getElementById('form-error').textContent='Speichern fehlgeschlagen. Die Änderungen bleiben hier erhalten; bitte vor dem Schließen sichern.';}
 }
 if(event.target.id==='pair-form'){try{const result=await api('keys',{method:'POST',body:JSON.stringify(values)});tokenResult=result.token;render();notify('Kopplungsschlüssel erstellt.');}catch(e){notify(e.message,true);}}
});
